export function findSubject(id) {
  return SUBJECTS.find(subject => subject.id === id);
}

export function findTopic(subjectId, topicId) {
  return findSubject(subjectId)?.topics.find(topic => topic.id === topicId);
}

export function totalTopics() {
  return SUBJECTS.reduce((sum, subject) => sum + subject.topics.length, 0);
}
